// Prepare time series data for forecasting
const items = $input.all();

const timeSeries = items.map(item => ({
  date: new Date(item.json.date).toISOString().split('T')[0],
  value: parseFloat(item.json.total_amount || item.json.count),
  count: parseInt(item.json.count),
  avg_value: parseFloat(item.json.avg_amount)
}));

// Calculate basic statistics
const values = timeSeries.map(t => t.value);
const mean = values.reduce((sum, v) => sum + v, 0) / values.length;
const variance = values.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / values.length;
const stdDev = Math.sqrt(variance);

// Detect trend (simple linear regression)
const n = timeSeries.length;
const sumX = Array.from({length: n}, (_, i) => i).reduce((sum, x) => sum + x, 0);
const sumY = values.reduce((sum, v) => sum + v, 0);
const sumXY = values.reduce((sum, v, i) => sum + (i * v), 0);
const sumX2 = Array.from({length: n}, (_, i) => i).reduce((sum, x) => sum + (x * x), 0);

const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
const intercept = (sumY - slope * sumX) / n;

const trendDirection = slope > 0.1 ? 'increasing' : slope < -0.1 ? 'decreasing' : 'stable';

// Detect seasonality (simplified - check for weekly patterns)
const weeklyAverages = {};
timeSeries.forEach(t => {
  const dayOfWeek = new Date(t.date).getDay();
  if (!weeklyAverages[dayOfWeek]) {
    weeklyAverages[dayOfWeek] = { sum: 0, count: 0 };
  }
  weeklyAverages[dayOfWeek].sum += t.value;
  weeklyAverages[dayOfWeek].count += 1;
});

const seasonalityIndex = Object.keys(weeklyAverages).map(day => ({
  day_of_week: parseInt(day),
  avg_value: weeklyAverages[day].sum / weeklyAverages[day].count
}));

return {
  json: {
    analysis_id: `forecast_${Date.now()}`,
    timestamp: new Date().toISOString(),
    historical_data: timeSeries,
    statistics: {
      data_points: n,
      mean: parseFloat(mean.toFixed(2)),
      std_dev: parseFloat(stdDev.toFixed(2)),
      min: Math.min(...values),
      max: Math.max(...values)
    },
    trend_analysis: {
      direction: trendDirection,
      slope: parseFloat(slope.toFixed(4)),
      intercept: parseFloat(intercept.toFixed(2))
    },
    seasonality: seasonalityIndex
  }
};

