const items = $input.all();
const baseData = items.find(item => item.json.analysis_id)?.json;

// Extract GPT-4 forecast
const gptResult = items.find(item => {
  try {
    const content = item.json.choices?.[0]?.message?.content;
    if (content) {
      const parsed = JSON.parse(content);
      return parsed.forecast !== undefined;
    }
  } catch (e) {}
  return false;
});
const gptForecast = gptResult ? JSON.parse(gptResult.json.choices[0].message.content) : null;

// Extract Python ML forecast
const pythonResult = items.find(item => item.json.forecasts || item.json.predictions);
const pythonForecast = pythonResult?.json;

// Combine forecasts (ensemble method - weighted average)
const combinedForecast = [];
if (gptForecast && pythonForecast) {
  for (let i = 0; i < 7; i++) {
    const gptPred = gptForecast.forecast[i];
    const pythonPred = pythonForecast.forecasts?.arima?.[i] || pythonForecast.predictions?.[i];

    if (gptPred && pythonPred) {
      const date = gptPred.date;
      const gptValue = gptPred.predicted_value;
      const pythonValue = pythonPred.value || pythonPred.predicted_value;

      // Weighted average: 40% GPT, 60% Statistical
      const ensembleValue = (gptValue * 0.4 + pythonValue * 0.6);

      // Confidence interval
      const gptLower = gptPred.confidence_interval?.lower || gptValue * 0.9;
      const gptUpper = gptPred.confidence_interval?.upper || gptValue * 1.1;
      const pythonLower = pythonPred.confidence_interval?.lower || pythonValue * 0.9;
      const pythonUpper = pythonPred.confidence_interval?.upper || pythonValue * 1.1;

      combinedForecast.push({
        date: date,
        predicted_value: parseFloat(ensembleValue.toFixed(2)),
        confidence_interval: {
          lower: parseFloat(Math.min(gptLower, pythonLower).toFixed(2)),
          upper: parseFloat(Math.max(gptUpper, pythonUpper).toFixed(2))
        },
        confidence_score: parseFloat(((gptPred.confidence_score || 0.8) * 0.5 + 0.85 * 0.5).toFixed(2)),
        models_agreement: Math.abs(gptValue - pythonValue) / ((gptValue + pythonValue) / 2) < 0.15
      });
    }
  }
}

// Calculate forecast accuracy metrics (using recent historical data)
const historicalValues = baseData?.historical_data.slice(-7).map(d => d.value) || [];
const avgHistorical = historicalValues.reduce((sum, v) => sum + v, 0) / historicalValues.length;
const forecastedAvg = combinedForecast.reduce((sum, f) => sum + f.predicted_value, 0) / combinedForecast.length;
const percentChange = ((forecastedAvg - avgHistorical) / avgHistorical * 100).toFixed(2);

// Generate insights
const insights = [
  `Forecast predicts ${percentChange > 0 ? 'an increase' : 'a decrease'} of ${Math.abs(percentChange)}% compared to recent average`,
  `Trend direction: ${baseData?.trend_analysis.direction}`,
  `Data quality: ${baseData?.statistics.data_points >= 60 ? 'Good (60+ days)' : 'Fair (less than 60 days)'}`,
  ...(gptForecast?.insights || [])
];

const result = {
  analysis_id: baseData?.analysis_id,
  timestamp: baseData?.timestamp,
  forecast_period: `${new Date().toISOString().split('T')[0]} to ${combinedForecast[combinedForecast.length-1]?.date || 'N/A'}`,
  historical_summary: {
    data_points: baseData?.statistics.data_points,
    mean: baseData?.statistics.mean,
    trend: baseData?.trend_analysis.direction,
    seasonality_detected: baseData?.seasonality.length > 0
  },
  ensemble_forecast: combinedForecast,
  model_forecasts: {
    gpt4_forecast: gptForecast?.forecast || [],
    statistical_models: pythonForecast?.forecasts || {}
  },
  forecast_metrics: {
    avg_predicted_value: forecastedAvg.toFixed(2),
    percent_change_from_recent: `${percentChange}%`,
    avg_confidence_score: (combinedForecast.reduce((sum, f) => sum + f.confidence_score, 0) / combinedForecast.length).toFixed(2),
    models_agreement_rate: `${(combinedForecast.filter(f => f.models_agreement).length / combinedForecast.length * 100).toFixed(0)}%`
  },
  insights: insights,
  risk_factors: gptForecast?.risk_factors || [],
  methodology: gptForecast?.methodology || 'Ensemble: GPT-4 AI (40%) + Statistical Models (60%)',
  metadata: {
    models_used: ['gpt4', 'arima', 'prophet', 'exponential_smoothing'],
    processing_time_ms: Date.now() - new Date(baseData?.timestamp).getTime()
  }
};

return { json: result };

